CAT = "aereraAgreements"; SEG = "AGR"
# Bylaw No. (85) of 2006 Chapters Four and Five (Arts. 26 to 38) and the RERA Real Estate Brokerage Practice Guide
# (smart contracts A, B and F, amicable settlement).
